/**
 * Email-safe HTML generator.
 *
 * Email clients (Gmail, Outlook, etc.) strip <style> elements and external
 * stylesheets, so every visual property must be expressed as an inline
 * `style` attribute and layout must use nested tables instead of CSS boxes.
 *
 * Structure produced by renderEmail():
 *   - outer centering wrapper table (100% width)
 *   - single content table fixed at 600px total width
 *   - hidden preheader span (display:none + max-height:0 inline styles)
 *   - all visual styling via style="" attributes only — zero <style>
 *     or <link> elements anywhere in the output
 *   - bulletproof CTA: an <a> tag padded and colored directly (no <button>,
 *     which Outlook replaces with its own widget)
 */

const escapeHtml = (value) =>
  String(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");

/** Escape text but leave it safe to interpolate into a style attribute. */
const escapeStyleValue = (value) => escapeHtml(value).replace(/&#39;/g, "%27");

/**
 * Render an email-safe HTML document.
 *
 * @param {object} options
 * @param {string} [options.preheader]   Hidden preview text shown in the inbox list.
 * @param {string} [options.heading]     Main heading.
 * @param {string[]} [options.paragraphs] Body paragraphs.
 * @param {{label: string, url: string}} [options.cta] Call-to-action link.
 * @returns {string} Full HTML document string.
 */
export function renderEmail({ preheader = "", heading = "", paragraphs = [], cta } = {}) {
  const parts = [];

  parts.push('<!DOCTYPE html PUBLIC "-//W3C//DTD XHTML 1.0 Transitional//EN" "http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd">');
  parts.push(`<html xmlns="http://www.w3.org/1999/xhtml" lang="en" xml:lang="en">`);
  parts.push("<head>");
  parts.push('<meta http-equiv="Content-Type" content="text/html; charset=UTF-8" />');
  parts.push('<meta name="viewport" content="width=device-width, initial-scale=1" />');
  parts.push(`<title>${escapeHtml(heading || "")}</title>`);
  parts.push("</head>");

  // Reset margins/padding on body via attribute + inline style only.
  parts.push(
    `<body bgcolor="#f4f4f7" style="margin:0; padding:0; background-color:#f4f4f7;">`
  );

  // Center wrapper table: full-width, centers the fixed 600px content table.
  parts.push(
    `<table role="presentation" border="0" cellpadding="0" cellspacing="0" width="100%" style="margin:0; padding:0; background-color:#f4f4f7;">` +
      "<tr>" +
      `<td align="center" style="padding:24px 12px;">`
  );

  // Content container: fixed 600px total width.
  parts.push(
    `<table role="presentation" border="0" cellpadding="0" cellspacing="0" width="600" style="width:600px; max-width:600px; background-color:#ffffff;">`
  );

  // Preheader: invisible in the rendered email but picked up by inbox preview text.
  if (preheader) {
    parts.push(
      "<tr>" +
        '<td style="display:none; max-height:0; overflow:hidden; mso-hide:all; font-size:1px; line-height:1px; color:#ffffff;">' +
        `<span style="display:none; max-height:0; overflow:hidden; mso-hide:all; font-size:1px; line-height:1px; color:#ffffff;">${escapeHtml(preheader)}</span>` +
        "</td>" +
        "</tr>"
    );
  }

  // Heading row.
  if (heading) {
    parts.push(
      "<tr>" +
        `<td align="left" style="padding:32px 40px 8px 40px; font-family:'Helvetica Neue',Helvetica,Arial,sans-serif; font-size:26px; line-height:32px; color:#111111; font-weight:bold;">` +
        escapeHtml(heading) +
        "</td>" +
        "</tr>"
    );
  }

  // Paragraph rows.
  for (const paragraph of paragraphs) {
    parts.push(
      "<tr>" +
        `<td align="left" style="padding:8px 40px; font-family:'Helvetica Neue',Helvetica,Arial,sans-serif; font-size:16px; line-height:24px; color:#333333;">` +
        escapeHtml(paragraph) +
        "</td>" +
        "</tr>"
    );
  }

  // Bulletproof CTA: styled <a>, not a <button>, so Outlook renders it correctly.
  if (cta && cta.label && cta.url) {
    parts.push(
      "<tr>" +
        '<td align="center" style="padding:24px 40px 32px 40px;">' +
        `<a href="${escapeHtml(cta.url)}" target="_blank" style="display:inline-block; margin:0; padding:14px 36px; background-color:#2563eb; border-radius:6px; font-family:'Helvetica Neue',Helvetica,Arial,sans-serif; font-size:16px; line-height:20px; color:#ffffff; font-weight:bold; text-decoration:none; text-align:center;">` +
        `${escapeHtml(cta.label)}</a>` +
        "</td>" +
        "</tr>"
    );
  }

  // Footer spacer / closing of tables.
  parts.push(
    "<tr>" +
      '<td align="center" style="padding:24px 40px; font-family:\'Helvetica Neue\',Helvetica,Arial,sans-serif; font-size:12px; line-height:18px; color:#999999;">' +
      "You are receiving this email because you signed up for updates.</td>" +
      "</tr>"
  );
  parts.push("</table>");

  parts.push("</td></tr></table>");
  parts.push("</body>");
  parts.push("</html>");

  return parts.join("\n");
}

export default renderEmail;
export { escapeHtml };

