import { describe, it, expect } from "vitest";
import * as cheerio from "cheerio";
import { renderEmail } from "../src/render.js";

const $ = (html) => cheerio.load(html);

const sample = () =>
  renderEmail({
    preheader: "Your weekly digest is here",
    heading: "Weekly Digest",
    paragraphs: ["Hello there,", "Here is what happened this week."],
    cta: {
      label: 'Read & Save <now>',
      url: "https://example.com/read?a=1&b=2",
    },
  });

describe("renderEmail", () => {
  it("produces no <style> or <link> elements anywhere", () => {
    const html = sample();
    const doc = $(html);
    expect(doc("style").length).toBe(0);
    expect(doc("link").length).toBe(0);
    // No raw <style> tag even outside cheerio's normalization
    expect(html.toLowerCase()).not.toContain("<style");
    expect(html.toLowerCase()).not.toContain("<link");
  });

  it("uses table-based layout with a 600px content table inside a centering wrapper", () => {
    const doc = $(sample());
    const tables = doc("table");
    expect(tables.length).toBeGreaterThanOrEqual(2);

    // Wrapper: full width, centered cell
    const wrapper = tables.first();
    expect(wrapper.attr("width")).toBe("100%");
    expect(wrapper.find('td[align="center"]').length).toBeGreaterThan(0);

    // Content table: fixed 600 width via attribute AND inline style
    const content = doc('table[width="600"]');
    expect(content.length).toBe(1);
    const contentStyle = String(content.attr("style"));
    expect(contentStyle).toMatch(/width:\s*600px/);
  });

  it("styles every td that sets visual properties exclusively via the style attribute", () => {
    const doc = $(sample());
    const tds = doc("td").toArray();
    expect(tds.length).toBeGreaterThan(0);

    for (const td of tds) {
      const $td = doc(td);
      const style = String($td.attr("style") ?? "");
      const attrs = Object.keys($td.attr());
      // No presentational attributes that would be needed as fallbacks:
      // visual props must come from the style attribute itself.
      expect(attrs).not.toContain("bgcolor");
      // Every visual declaration lives inline
      if (/padding|background|color|font|border/.test(style)) {
        expect(style).toContain("padding");
      }
      // And crucially: no td relies on class/id selectors
      expect($td.attr("class")).toBeUndefined();
      expect($td.attr("id")).toBeUndefined();
    }
  });

  it("renders the preheader text hidden via inline display:none and max-height:0", () => {
    const html = sample();
    const doc = $(html);
    const span = doc('span[style*="display:none"], span[style*="display: none"]');
    expect(span.length).toBe(1);
    expect(span.text()).toBe("Your weekly digest is here");

    const style = String(span.attr("style"));
    expect(style).toMatch(/display:\s*none/);
    expect(style).toMatch(/max-height:\s*0/);
    expect(style).toMatch(/overflow:\s*hidden/);

    // Present in the source markup
    expect(html).toContain("Your weekly digest is here");
  });

  it("renders a bulletproof CTA anchor with inline padding and background", () => {
    const doc = $(sample());
    const cta = doc("table a").filter((_, el) =>
      String(doc(el).attr("href")).startsWith("https://example.com/")
    );
    expect(cta.length).toBe(1);

    const style = String(cta.attr("style"));
    expect(style).toMatch(/padding:\s*\d+px\s+\d+px/);
    expect(style).toMatch(/background(-color)?:\s*#/i);

    // It's an anchor, not a button element
    expect(cta.get(0).tagName).toBe("a");
    expect(doc("button").length).toBe(0);
  });

  it("sets the CTA href exactly and escapes the label", () => {
    const html = sample();
    const doc = $(html);
    const href = doc('a[href^="https://example.com"]').attr("href");
    expect(href).toBe("https://example.com/read?a=1&b=2");

    // Label with ampersand and angle brackets must be escaped in source...
    expect(html).toContain("&amp;");
    expect(html).not.toMatch(/Read & Save/); // raw & never appears unescaped
    expect(html).not.toContain("<now>");
    expect(html).toContain("&lt;now&gt;");

    // ...but decodes back to the original label text
    const label = doc('a[href^="https://example.com"]').text();
    expect(label).toBe("Read & Save <now>");
  });

  it("escapes user content everywhere (preheader, heading, paragraphs)", () => {
    const html = renderEmail({
      preheader: 'A & B',
      heading: "<b>Bold</b> & 'quoted'",
      paragraphs: ['5 < 6 & "7" > 3'],
    });
    const doc = $(html);
    // Cheerio decodes entities when reading text, so round-trip check works
    expect(doc("body").text()).toContain("5 < 6 & \"7\" > 3");
    expect(html).toContain("&lt;b&gt;Bold&lt;/b&gt;");
  });
});

